import{_ as s,o as e,c as i,ag as n}from"./chunks/framework.BZohXCq9.js";const k=JSON.parse('{"title":"RK3588 高性能相机流水线：从 V4L2 到算法消费者","description":"以单一采集所有者、DMA-BUF 与显式失败为核心设计 RK3588 相机数据链路","frontmatter":{"title":"RK3588 高性能相机流水线：从 V4L2 到算法消费者","description":"以单一采集所有者、DMA-BUF 与显式失败为核心设计 RK3588 相机数据链路","tags":["RK3588","V4L2","DMA-BUF","RGA","OpenCL"],"date":"2026/07/14"},"headers":[],"relativePath":"linux/rk3588-camera-pipeline.md","filePath":"linux/rk3588-camera-pipeline.md","lastUpdated":1784519165000}'),l={name:"linux/rk3588-camera-pipeline.md"};function p(t,a,r,h,o,c){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="rk3588-高性能相机流水线-从-v4l2-到算法消费者" tabindex="-1">RK3588 高性能相机流水线：从 V4L2 到算法消费者 <a class="header-anchor" href="#rk3588-高性能相机流水线-从-v4l2-到算法消费者" aria-label="Permalink to &quot;RK3588 高性能相机流水线：从 V4L2 到算法消费者&quot;">​</a></h1><p>在 RK3588 上做多路相机，性能问题通常不是某一个算子太慢，而是整条链路反复改变数据形态：采集一次、复制到共享内存、转成 BGR、上传 GPU、读回 CPU，再经 ROS 序列化发给算法。单看每一段都能运行，叠起来却会消耗大量 CPU、内存带宽和延迟预算。</p><h2 id="目标主链" tabindex="-1">目标主链 <a class="header-anchor" href="#目标主链" aria-label="Permalink to &quot;目标主链&quot;">​</a></h2><p>更清晰的生产主链可以收敛为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>V4L2 DMA-BUF capture</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>RGA：旋转 / 缩放 / 必要的格式变换</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>OpenCL：鱼眼矫正 / 拼接 / GPU 前处理</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Frame Broker：按 sequence 发布句柄与元数据</span></span>
<span class="line"><span>        ├── VINS</span></span>
<span class="line"><span>        ├── RKNN / 视觉算法</span></span>
<span class="line"><span>        └── MPP / 编码推流</span></span></code></pre></div><p>这里最重要的不是把所有模块都换成硬件加速，而是让<strong>同一份帧数据沿主链向下流动</strong>。</p><h2 id="_1-只保留一个-camera-owner" tabindex="-1">1. 只保留一个 Camera Owner <a class="header-anchor" href="#_1-只保留一个-camera-owner" aria-label="Permalink to &quot;1. 只保留一个 Camera Owner&quot;">​</a></h2><p>相机设备应该只有一个进程负责打开、配置、排队和回收 buffer。其他模块通过 broker 消费帧，不再各自打开 V4L2 或维护另一套采集逻辑。</p><p>单一 owner 可以统一处理：</p><ul><li>设备状态与重连；</li><li>固定 DMA-BUF 池；</li><li>多相机 bundle、trigger 与 sequence；</li><li>buffer 的借用和回收；</li><li>运行时健康状态。</li></ul><p>一旦多个服务都能成为采集 owner，设备占用、重复 buffer pool 和重启顺序就会变得难以推理。</p><h2 id="_2-同步属于采集合同-不属于-ros-topic" tabindex="-1">2. 同步属于采集合同，不属于 ROS topic <a class="header-anchor" href="#_2-同步属于采集合同-不属于-ros-topic" aria-label="Permalink to &quot;2. 同步属于采集合同，不属于 ROS topic&quot;">​</a></h2><p>多相机同步信息应和帧一起进入 typed metadata，例如：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> FrameMeta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bundle_seq;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> trigger_seq;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> capture_timestamp_ns;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> width;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> height;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stride;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PixelFormat format;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>消费者按 <code>bundle_seq</code> 或 <code>trigger_seq</code> 判断同组帧，而不是依赖进程内计数器或可能被中间件改写的通用消息序号。</p><h2 id="_3-rga-与-opencl-各做擅长的工作" tabindex="-1">3. RGA 与 OpenCL 各做擅长的工作 <a class="header-anchor" href="#_3-rga-与-opencl-各做擅长的工作" aria-label="Permalink to &quot;3. RGA 与 OpenCL 各做擅长的工作&quot;">​</a></h2><p>RGA 适合规则明确的二维操作，如 resize、rotate、crop 和部分格式转换。OpenCL 更适合鱼眼 remap、查表和并行像素变换。MPP 则留给编解码。</p><p>合理的职责划分能避免为了“GPU 化”把简单缩放也绕进复杂 kernel，也避免把 remap 长期留在 CPU <code>cv::remap</code> 上。</p><h2 id="_4-broker-传递的是能力-不是像素副本" tabindex="-1">4. Broker 传递的是能力，不是像素副本 <a class="header-anchor" href="#_4-broker-传递的是能力-不是像素副本" aria-label="Permalink to &quot;4. Broker 传递的是能力，不是像素副本&quot;">​</a></h2><p>Broker 应发送 DMA-BUF fd、几何信息、时间戳和 sequence，而不是重新序列化整张图像。进程间传递可用 Unix Domain Socket + <code>SCM_RIGHTS</code>，进程内消费者则直接持有 frame handle。</p><p>但 fd 传递只是接口的一半，另一半是 buffer ownership。生产实现必须定义消费者何时完成、生产者何时可以复用 buffer，不能把“fd 已发送”当作“帧已安全交付”。</p><h2 id="_5-生产链路不做静默-runtime-fallback" tabindex="-1">5. 生产链路不做静默 runtime fallback <a class="header-anchor" href="#_5-生产链路不做静默-runtime-fallback" aria-label="Permalink to &quot;5. 生产链路不做静默 runtime fallback&quot;">​</a></h2><p>从 GPU 路径静默回退到 CPU，看起来更“稳”，实际会让系统进入一种功能还在、性能合同已经失效的状态。对于固定硬件的生产系统，更可控的策略是：</p><ol><li>启动时检查能力与配置；</li><li>主链初始化失败就明确失败；</li><li>health 记录错误原因；</li><li>由 systemd 或上层 supervisor 重启；</li><li>legacy CPU 路径只保留为诊断工具，不作为生产自动回退。</li></ol><p>这样，故障会以可观测的方式暴露，而不是在负载高峰变成随机掉帧。</p><h2 id="验收清单" tabindex="-1">验收清单 <a class="header-anchor" href="#验收清单" aria-label="Permalink to &quot;验收清单&quot;">​</a></h2><ul><li>V4L2 设备只有一个 owner；</li><li>buffer pool 数量固定，生命周期可追踪；</li><li>RGA、OpenCL、NPU、MPP 的输入输出格式明确；</li><li>sequence、trigger、timestamp 随帧传递；</li><li>消费者超时不会导致生产者复用仍在使用的 buffer；</li><li>GPU/RGA 的真实忙闲增量可观测；</li><li>主链失败会明确报错，不会悄悄切到另一条性能不可控的路径。</li></ul><p>高性能相机系统的核心不是堆更多加速单元，而是建立一条<strong>所有权清晰、数据形态稳定、失败可见</strong>的主链。</p>`,28)])])}const u=s(l,[["render",p]]);export{k as __pageData,u as default};
